cat > mapfit.py << 'EOF'
import sys, csv, importlib.util, numpy as np, pymc as pm
path = sys.argv[1]
spec = importlib.util.spec_from_file_location("m", path); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
rows = list(csv.DictReader(open("/scr/wurgaft/auto-psych/agent_trees/2485af553ddb9dd3/repo/_runs/cell_1/experiment3/model_loop/responses.csv")))
cache = {}
feats = []
for r in rows:
    k = (r["number_set"], r["target"])
    if k not in cache: cache[k] = m.compute_features(*k)
    feats.append(cache[k])
data = {k: np.array([f[k] for f in feats], dtype="float64") for k in feats[0]}
data["rating"] = np.array([int(r["rating"]) for r in rows], dtype="int64")
with m.model:
    names = {v.name for v in m.model.data_vars}
    pm.set_data({k: v for k, v in data.items() if k in names})
    best = None
    for seed in range(3):
        mp = pm.find_MAP(progressbar=False, seed=seed, maxeval=5000)
        lp = m.model.compile_logp()(mp)
        ll = float(np.sum(data["rating"]*np.log(mp["p_yes"])+(1-data["rating"])*np.log(1-mp["p_yes"])))
        print(seed, "logp", round(float(lp),2), "loglik", round(ll,2), flush=True)
        if best is None or ll > best[0]: best = (ll, mp)
    for k, v in best[1].items():
        if not k.endswith("__") and np.size(v) < 20: print(k, np.round(v, 3))
EOF
